"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["54022"],{45397(e){e.exports=JSON.parse('{"id":"FIN-742","slug":"warrant","term":"Warrant","also_known_as":[],"difficulty":"Intermediate","definition":"A warrant is a security issued by a company that gives its holder the right, but not the obligation, to buy the company\'s shares at a set price before a specific date.","explanation":["Warrants are similar to call options, but with a key difference: they are issued by the company itself, and when they are exercised, the company creates new shares. This means warrants can dilute existing shareholders.","Companies often attach warrants to bonds or preferred shares to make them more attractive to investors, allowing them to borrow at lower interest rates. Warrants may also be issued in restructurings, to lenders or as part of special purpose acquisition company deals.","For example, a warrant might give the right to buy one share at 20 at any time over the next five years. If the share price rises to 26, the warrant has an intrinsic value of 6. If the share price stays below 20, the warrant may expire worthless.","Warrants usually have much longer lives than exchange-traded options, often several years. Some are traded on stock exchanges separately from the bonds or shares they were issued with.","Because a small investment in warrants can produce large gains or losses relative to the share price, they carry high risk. When analysing a company, investors should consider outstanding warrants, since their exercise would increase the number of shares."],"note":"","total":1500,"prev":{"slug":"voting-rights","term":"Voting Rights"},"next":{"slug":"wash-sale-rule","term":"Wash-Sale Rule"}}')}}]);